CREATE OR REPLACE FUNCTION public.review_membership_evidence(_id uuid,_approve boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.membership_requests; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'ADMIN_ONLY'; END IF; SELECT * INTO r FROM public.membership_requests WHERE id=_id FOR UPDATE; IF r.id IS NULL OR r.status<>'pending' THEN RAISE EXCEPTION 'REVIEW_REQUIRED'; END IF; UPDATE public.membership_requests SET status=CASE WHEN _approve THEN 'approved' ELSE 'rejected' END,reviewed_at=now(),reviewed_by=auth.uid() WHERE id=_id; UPDATE public.membership_access SET source=CASE WHEN _approve THEN 'confirmed' ELSE source END,starts_at=CASE WHEN _approve THEN now() ELSE starts_at END,ends_at=CASE WHEN _approve THEN now()+interval '1 month' ELSE ends_at END,revoked_at=CASE WHEN _approve THEN NULL ELSE now() END,granted_by=auth.uid() WHERE request_id=_id; IF _approve AND r.payer_id=r.user_id THEN PERFORM public.confirm_referral_cash(r.user_id,r.reference,r.amount::bigint*100); END IF; INSERT INTO public.messages(sender_id,receiver_id,body,is_auto) VALUES(auth.uid(),r.user_id,CASE WHEN _approve THEN 'మీరు అమౌంట్ కట్టారని భావిస్తున్నాము. 24 గంటల్లో మీ సబ్స్క్రైబర్ యాక్టివేషన్ అవుతుంది.' ELSE 'మీ చెల్లింపు నిర్ధారణ కాలేదు. అడ్మిన్ తో చాట్ చేయండి.' END,true); END $$;

CREATE OR REPLACE FUNCTION public.my_free_work_bell_notices() RETURNS TABLE(notification_id uuid,ringer uuid,section text,category text,area text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
SELECT q.notification_id, i.user_id, i.section, i.category, i.area
FROM public.free_work_notice_queue q
JOIN public.free_work_interests i ON i.entry_id=split_part(q.entry_id,':',1) AND i.user_id::text=split_part(q.entry_id,':',2)
WHERE q.user_id=auth.uid() AND q.source='bell' AND q.notification_id IS NOT NULL AND public.account_allowed(i.user_id)
$$;
REVOKE ALL ON FUNCTION public.my_free_work_bell_notices() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.my_free_work_bell_notices() TO authenticated;